// src/hooks/UseWatchedFolders.js
import { useCallback, useEffect, useState } from 'react';
import {
  fetchWatchedFolders,
  createWatchedFolder,
  deleteWatchedFolder,
  pickWatchedFolderPath,
} from '../api/SettingApi';

export function useWatchedFolders() {
  const [folders, setFolders] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const normalizeFolders = useCallback((data) => {
    const list = Array.isArray(data) ? data : (data?.items ?? []);
    return list.map((it) => ({
      id: it.id ?? it.folderId ?? it.path,
      name: it.name ?? it.folderName ?? it.path ?? '폴더',
      path: it.path,
      createdAt: it.createdAt,
    }));
  }, []);

  const refresh = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await fetchWatchedFolders();
      setFolders(normalizeFolders(data));
    } catch (e) {
      setError(e);
      setFolders([]);
    } finally {
      setLoading(false);
    }
  }, [normalizeFolders]);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // ✅ 다이얼로그로 폴더 선택 -> 서버에 등록
  const promptAndAddFolder = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      const picked = await pickWatchedFolderPath();
      const path = (typeof picked === 'string' ? picked : picked?.path) || '';

      if (!path.trim()) return;

      // name은 비워도 백엔드에서 name==blank면 path로 자동 처리
      await createWatchedFolder({ name: '', path: path.trim() });
      await refresh();
    } catch (e) {
      setError(e);
      alert(`폴더 추가 실패: ${e.message}`);
    } finally {
      setLoading(false);
    }
  }, [refresh]);

  const removeFolder = useCallback(
    async (id) => {
      try {
        setLoading(true);
        setError(null);
        await deleteWatchedFolder(id);
        await refresh();
      } catch (e) {
        setError(e);
        alert(`폴더 삭제 실패: ${e.message}`);
      } finally {
        setLoading(false);
      }
    },
    [refresh]
  );

  return { folders, loading, error, refresh, promptAndAddFolder, removeFolder };
}
